# Arguments an alias fixes, because its 1e name picked one variant of a 2.0
# function that now does both. The caller's own value wins.
xucinet_1e_args <- list(
  xAlterCompositionCat = list(type = "categorical"),
  xAlterCompositionCon = list(type = "continuous"),
  xEgoAlterSimilarityCat = list(type = "categorical"),
  xEgoAlterSimilarityCon = list(type = "continuous"),
  xContinuousCorePeriphery = list(type = "continuous"),
  xConcentration = list(type = "continuous"),
  xDiscreteCorePeriphery = list(type = "categorical")
)

# Aliases whose 2.0 target is not coming. These stop with the explanation
# below rather than the generic "not written yet" message, which would be a
# lie: nothing is going to land.
xucinet_1e_withdrawn <- c(
  xCreateProject = "xucinet 2.0 has no project object. A UCINET project was a folder of datasets; here you read each dataset with xread() and keep them in whatever R structure suits, a list most often. See ?xread and ?xmatch.",
  xAddToProject = "xucinet 2.0 has no project object. Read the dataset with xread() and keep it beside the others; xmatch() lines several up on one node set and xjoin() stacks them into one multi-relation dataset.",
  xAddAttributesToProject = "xucinet 2.0 has no project object. Attributes live in their own data frame; xmatch(net, attributes, attach = TRUE) puts them on the network.",
  xWalkTrap = "Walktrap is not in xucinet 2.0: the book's chapter on subgroups uses Louvain, fast greedy, Girvan-Newman, label propagation and factions instead. xlouvain(), or xcommunities() for all five side by side, is the nearest replacement; igraph::cluster_walktrap() still computes Walktrap itself.",
  xWalktrap = "Walktrap is not in xucinet 2.0: the book's chapter on subgroups uses Louvain, fast greedy, Girvan-Newman, label propagation and factions instead. xlouvain(), or xcommunities() for all five side by side, is the nearest replacement; igraph::cluster_walktrap() still computes Walktrap itself.",
  xNegativeDegreeCentrality = "Negative-tie degree is degree on the negative-tie relation: xdegree(net, relation = \"negative\"), or xdegree() on the negative-tie matrix.",
  xRemoveFromProject = "xucinet 2.0 has no project object. Datasets are ordinary R objects, so drop one the way you would drop any other; xunpack() is what splits a multi-relation dataset into separate ones."
)

#' The 1e alias table
#'
#' @return A named character vector: 1e name to 2.0 name.
#' @keywords internal
#' @export
xucinet_1e_names <- function() xucinet_1e_map

# One wrapper body for all of them. A target that does not exist yet is not an
# error in the alias layer, it is a routine not written yet, and the message
# says which one so the reader knows what to wait for.
alias_1e <- function(old, new, ...) {
  # [[ ]] on a named vector errors for a name that is not there, and most
  # aliases have no note.
  note <- if (old %in% names(xucinet_1e_notes)) xucinet_1e_notes[[old]] else ""
  if (old %in% names(xucinet_1e_withdrawn)) {
    stop(old, "() was an ASNR 1e name, and xucinet 2.0 has no replacement ",
         "for it.\n  ", xucinet_1e_withdrawn[[old]], call. = FALSE)
  }
  fn <- get0(new, envir = asNamespace("xucinet"), mode = "function")
  if (is.null(fn)) {
    stop(old, "() was the ASNR 1e name for what xucinet 2.0 calls ", new, "().\n",
         "  ", new, "() is not written yet; it belongs to a later phase.\n",
         "  This wrapper exists so the 1e name resolves, and will start working",
         " the day ", new, "() lands.",
         if (nzchar(note)) paste0("\n  ", note) else "", call. = FALSE)
  }
  message(old, "() is the ASNR 1e name. xucinet 2.0 calls it ", new, "().",
          if (nzchar(note)) paste0("\n  ", note) else "")
  # Built as a call and evaluated here, so that `...` is forwarded unevaluated
  # and the 2.0 function still sees the caller's expression for its title.
  fixed <- xucinet_1e_args[[old]]
  if (!is.null(fixed)) {
    fixed <- fixed[setdiff(names(fixed), ...names())]
    return(eval(as.call(c(list(fn, quote(...)), fixed))))
  }
  fn(...)
}


